package com.sports.payment_service.repository; import com.sports.payment_service.entity.*; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface PaymentRepository extends JpaRepository<Payment,Long>{ Optional<Payment> findByReference(String reference); List<Payment> findByCoachIdOrderByCreatedAtDesc(Long coachId); List<Payment> findAllByOrderByCreatedAtDesc(); List<Payment> findByStatusOrderByCreatedAtDesc(PaymentStatus status); List<Payment> findByCoachIdAndStatusOrderByCreatedAtDesc(Long coachId,PaymentStatus status); Optional<Payment> findFirstByCoachIdAndStatusOrderByPaidAtDesc(Long coachId,PaymentStatus status); }